   <div class="card">${ch('Skills Overview','<button class="text-[11.5px] font-semibold text-brand">View Details</button>')}<div class="px-4 pb-4 space-y-2.5">${[['UI/UX Design',70,'blue'],['Frontend',80,'emerald'],['Backend',65,'amber'],['Testing',50,'purple'],['Project Management',40,'pink'],['Communication',85,'blue']].map(([t,p,c])=>`<div class="flex items-center gap-3"><span class="w-32 text-[11.5px] font-bold text-slate-700">${t}</span><div class="flex-1">${hbar(p,c,6)}</div><span class="text-[11px] font-bold w-9 text-right">${p}%</span></div>`).join('')}</div></div>
