function openTask(){openModal('Add New Task',`${fld('Task Title',`<input class="inp w-full" id="m-t" placeholder="e.g. Design dashboard UI">`)}<div class="grid grid-cols-2 gap-3">${fld('Project',`<select class="inp w-full"><option>Workforce Dashboard</option><option>Mobile App</option></select>`)}${fld('Priority',`<select class="inp w-full"><option>High</option><option>Medium</option><option>Low</option></select>`)}</div><div class="grid grid-cols-2 gap-3">${fld('Due Date',`<input type="date" class="inp w-full" value="2026-10-02">`)}${fld('Assignee',`<select class="inp w-full"><option>Amit Verma</option><option>Neha Singh</option></select>`)}</div>`,()=>toast('Task "'+($('#m-t').value||'New')+'" created'));}

