const KAN=()=>{const cols=[['To Do','slate',[['Create user authentication flow','Frontend','High','03 Oct',[7,25]],['Design dashboard wireframes','Design','Medium','05 Oct',[44]],['Setup project infrastructure','DevOps','High','04 Oct',[12]]]],['In Progress','blue',[['Build dashboard UI components','Frontend','High','30 Sep',[12,59]],['Integrate time tracking API','Backend','Medium','02 Oct',[12,60]],['Create analytics charts','Frontend','Medium','01 Oct',[13,47]]]],['Review','amber',[['UI/UX design review','Design','High','29 Sep',[44,47]],['API documentation','Documentation','Medium','01 Oct',[60]]]],['Completed','emerald',[['Project kickoff meeting','Management','Low','25 Sep',[45,13]],['Setup development environment','DevOps','High','26 Sep',[12]]]]];
 return cols.map(([n,c,tasks])=>{const pc={High:'red',Medium:'amber',Low:'emerald'};return `<div class="rounded-xl bg-slate-50 border border-slate-100 p-2.5"><div class="flex items-center gap-2 px-1 pb-2"><span class="w-2 h-2 rounded-full bg-${c==='slate'?'slate-400':c+'-500'}"></span><span class="font-display font-bold text-[12.5px]">${n}</span><span class="text-[10px] font-bold text-slate-400">(${tasks.length})</span></div>${tasks.map(([t,tag,pr,due,as])=>{const tc={Frontend:'blue',Design:'purple',Backend:'blue',DevOps:'red',Documentation:'emerald',Management:'slate'}[tag];return `<div class="bg-white rounded-lg border border-slate-100 p-2.5 mb-2"><p class="text-[12px] font-bold text-slate-800 mb-1.5">${t}</p><div class="flex items-center gap-1.5 mb-2"><span class="text-[9px] font-bold px-1.5 py-0.5 rounded bg-${tc}-50 text-${tc}-600">${tag}</span><span class="inline-flex items-center gap-1 text-[9px] font-bold px-1.5 py-0.5 rounded bg-${pc[pr]}-50 text-${pc[pr]}-600"><span class="w-1 h-1 rounded-full bg-${pc[pr]}-500"></span>${pr}</span></div><div class="flex items-center gap-2">${avS(as)}<span class="ml-auto inline-flex items-center gap-1 text-[9.5px] text-slate-400"><i data-lucide="calendar" class="w-3 h-3"></i>${due}</span></div></div>`;}).join('')}</div>`;}).join('');};
