 $('#view-actions').innerHTML=`<button class="btn-o"><i data-lucide="share-2" class="w-4 h-4"></i>Share</button><button class="btn-p" onclick="openTask()"><i data-lucide="plus" class="w-4 h-4"></i>Add Task</button>`;
 return `<p class="text-[11.5px] text-slate-400 mb-3 -mt-2 flex items-center gap-1.5"><i data-lucide="folder" class="w-3.5 h-3.5"></i>Projects <i data-lucide="chevron-right" class="w-3 h-3"></i><span class="text-slate-600 font-semibold">Workforce Dashboard</span></p>
 <div class="flex items-start gap-4 flex-wrap mb-4"><div class="w-12 h-12 rounded-xl bg-gradient-to-br from-blue-500 to-blue-700 flex items-center justify-center flex-none shadow-lg"><i data-lucide="hexagon" class="w-6 h-6 text-white"></i></div>
 <div class="flex-1 min-w-[260px]"><div class="flex items-center gap-2"><h2 class="font-display font-extrabold text-[20px]">Workforce Dashboard</h2><i data-lucide="star" class="w-4 h-4 text-amber-400 fill-amber-400"></i></div><p class="text-[12.5px] text-slate-500">Build the next generation team management and productivity platform.</p>
 <div class="flex gap-1.5 mt-2 flex-wrap">${pillN('Active','emerald')}${pillN('High Priority','red')}${pillN('Product','blue')}</div></div></div>
 <div class="grid grid-cols-1 lg:grid-cols-4 gap-4"><div class="lg:col-span-3 grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-3">${KAN()}</div>
 <div class="space-y-4"><div class="card">${ch('Project Members (8)','<button class="text-[11.5px] font-semibold text-brand">Manage →</button>')}<div class="px-4 pb-4">${avS([47,12,45,59,44,7,51,25])}<p class="text-[10.5px] text-slate-400 mt-2">8 members · 2 on leave</p></div></div>
 <div class="card">${ch('Progress','<button class="text-[11.5px] font-semibold text-brand">View Report →</button>')}<div class="px-4 pb-4"><div class="flex justify-between text-[11px] font-bold mb-1.5"><span class="text-slate-400">Completion</span><span>47%</span></div>${hbar(47,'emerald',8)}<div class="grid grid-cols-3 gap-2 mt-3 text-center">${[['20','Completed'],['16','In Progress'],['6','To Do']].map(([v,l])=>`<div class="rounded-lg bg-slate-50 py-2"><p class="font-extrabold text-[16px]">${v}</p><p class="text-[9.5px] font-semibold text-slate-500">${l}</p></div>`).join('')}</div></div></div>
 <div class="card">${ch('Quick Links')}<div class="px-2 pb-3">${[['Figma Design','palette','purple'],['GitHub Repository','github','slate'],['Staging Environment','server','amber'],['API Documentation','book-open','blue']].map(([n,ic,c])=>`<div class="flex items-center gap-3 px-2 py-2 hover:bg-slate-50 rounded-lg"><span class="w-7 h-7 rounded-lg bg-${c}-100 flex items-center justify-center"><i data-lucide="${ic}" class="w-3.5 h-3.5 text-${c}-600"></i></span><span class="flex-1 text-[12.5px] font-bold">${n}</span><button class="text-[11px] font-bold text-brand" data-toast="Opening link">Open<i data-lucide="arrow-right" class="w-3 h-3 inline"></i></button></div>`).join('')}</div></div>
 </div></div>`;
