   <div class="card">${ch('Recent Activity',vAll)}<div class="px-2 pb-3">${[['Priya Sharma uploaded Employee Handbook 2026.pdf','2 hours ago',45],['Rohan Das uploaded ID Proof - Rohan Das.pdf','5 hours ago',13],['Aman Verma updated Leave Policy.pdf','1 day ago',7],['Sneha Iyer uploaded Experience Letter.pdf','1 day ago',25]].map(([t,d,img])=>`<div class="flex gap-2.5 px-2 py-2">${av(img,28)}<div class="min-w-0"><p class="text-[11px] font-bold text-slate-700 leading-snug">${t}</p><p class="text-[9.5px] text-slate-400">${d}</p></div></div>`).join('')}</div></div>
